func normalizeNavaidRefKey(raw string) string {
	s := strings.ToLower(strings.TrimSpace(raw))
	s = strings.TrimPrefix(s, "#")
	s = strings.TrimPrefix(s, "urn:uuid:")
	s = strings.TrimPrefix(s, "uuid.")
	return s
}

func extractGMLCodeName(names []*gml.CodeType) string {
	for _, n := range names {
		if n != nil && strings.TrimSpace(n.EnclosedText) != "" {
			return strings.TrimSpace(n.EnclosedText)
		}
	}
	return ""
}

func formatXlinkRefLabel(title, href string) string {
	t := strings.TrimSpace(title)
	h := strings.TrimSpace(href)
	if t != "" {
		return t
	}
	h = strings.TrimPrefix(h, "#")
	h = strings.TrimPrefix(h, "urn:uuid:")
	return h
}

func formatFrequencyVal(f *aixmdatatypes.ValFrequencyType) string {
	if f == nil || strings.TrimSpace(f.EnclosedText) == "" {
		return ""
	}
	val := strings.TrimSpace(f.EnclosedText)
	uom := strings.TrimSpace(f.Uom)
	switch strings.ToUpper(uom) {
	case "MHZ":
		uom = "MHz"
	case "KHZ":
		uom = "kHz"
	case "GHZ":
		uom = "GHz"
	}
	if uom != "" {
		return val + " " + uom
	}
	return val
}

func formatDistanceVal(d *aixmdatatypes.ValDistanceType) string {
	if d == nil || strings.TrimSpace(d.EnclosedText) == "" {
		return ""
	}
	val := strings.TrimSpace(d.EnclosedText)
	uom := strings.TrimSpace(d.Uom)
	if uom != "" {
		return val + " " + uom
	}
	return val
}

func formatVerticalDistVal(v *aixmdatatypes.ValDistanceVerticalType) (meters float64, ok bool, label string) {
	if v == nil || strings.TrimSpace(v.EnclosedText) == "" {
		return 0, false, ""
	}
	txt := strings.TrimSpace(v.EnclosedText)
	uom := strings.ToUpper(strings.TrimSpace(v.Uom))
	if uom == "FL" {
		label = "FL" + txt
	} else if uom != "" {
		label = txt + " " + uom
	} else {
		label = txt
	}
	num, err := strconv.ParseFloat(txt, 64)
	if err != nil {
		return 0, false, label
	}
	switch uom {
	case "FT":
		return num * 0.3048, true, label
	case "FL":
		return num * 30.48, true, label
	case "KM":
		return num * 1000.0, true, label
	default:
		return num, true, label
	}
}

func isCRS84LonLat(srsName string) bool {
	upper := strings.ToUpper(strings.TrimSpace(srsName))
	return strings.Contains(upper, "CRS84") || strings.Contains(upper, "CRS:84")
}

func parseDirectPositionLatLon(pos *gml.DirectPositionType, parentSrs string) (lat, lon float64, ok bool) {
	if pos == nil {
		return 0, 0, false
	}
	fields := strings.Fields(pos.EnclosedText)
	if len(fields) < 2 {
		return 0, 0, false
	}
	v1, err1 := strconv.ParseFloat(fields[0], 64)
	v2, err2 := strconv.ParseFloat(fields[1], 64)
	if err1 != nil || err2 != nil {
		return 0, 0, false
	}
	srs := pos.SrsName
	if srs == "" {
		srs = parentSrs
	}
	if isCRS84LonLat(srs) {
		lat, lon = v2, v1
	} else {
		lat, lon = v1, v2
	}
	if math.Abs(lat) > 90.0 && math.Abs(lon) <= 90.0 {
		lat, lon = lon, lat
	}
	if lat < -90.0 || lat > 90.0 || lon < -180.0 || lon > 180.0 {
		return 0, 0, false
	}
	return lat, lon, true
}

func extractElevatedPointCoord(epProp *aixmfeatures.ElevatedPointPropertyType) (lat, lon, elevM float64, hasCoord, hasElev bool, elevLabel string) {
	if epProp == nil || epProp.ElevatedPoint == nil {
		return 0, 0, 0, false, false, ""
	}
	ep := epProp.ElevatedPoint
	lat, lon, hasCoord = parseDirectPositionLatLon(ep.Pos, ep.SrsName)
	elevM, hasElev, elevLabel = formatVerticalDistVal(ep.Elevation)
	if elevLabel != "" && ep.VerticalDatum != nil && strings.TrimSpace(ep.VerticalDatum.EnclosedText) != "" {
		elevLabel += " (" + strings.TrimSpace(ep.VerticalDatum.EnclosedText) + ")"
	}
	return lat, lon, elevM, hasCoord, hasElev, elevLabel
}

func extractPointPropCoord(ptProp *aixmfeatures.PointPropertyType) (lat, lon, elevM float64, hasCoord, hasElev bool, elevLabel string) {
	if ptProp == nil {
		return 0, 0, 0, false, false, ""
	}
	if ptProp.ElevatedPoint != nil {
		ep := ptProp.ElevatedPoint
		lat, lon, hasCoord = parseDirectPositionLatLon(ep.Pos, ep.SrsName)
		elevM, hasElev, elevLabel = formatVerticalDistVal(ep.Elevation)
		return lat, lon, elevM, hasCoord, hasElev, elevLabel
	}
	if ptProp.Point != nil {
		pt := ptProp.Point
		lat, lon, hasCoord = parseDirectPositionLatLon(pt.Pos, pt.SrsName)
		return lat, lon, 0, hasCoord, false, ""
	}
	return 0, 0, 0, false, false, ""
}

func extractEquipmentAuthorities(auths []*aixmfeatures.AuthorityForNavaidEquipmentPropertyType) []navaidAuthorityDetail {
	var out []navaidAuthorityDetail
	for _, ap := range auths {
		if ap == nil || ap.AuthorityForNavaidEquipment == nil {
			continue
		}
		auth := ap.AuthorityForNavaidEquipment
		role := "AUTHORITY"
		if auth.Type_XSD != nil && strings.TrimSpace(auth.Type_XSD.EnclosedText) != "" {
			role = strings.ToUpper(strings.TrimSpace(auth.Type_XSD.EnclosedText))
		}
		orgLabel := auth.Id
		href := ""
		if auth.TheOrganisationAuthority != nil {
			href = auth.TheOrganisationAuthority.Href
			lbl := formatXlinkRefLabel(auth.TheOrganisationAuthority.Title, auth.TheOrganisationAuthority.Href)
			if lbl != "" {
				orgLabel = lbl
			}
		}
		out = append(out, navaidAuthorityDetail{
			Role:     role,
			OrgLabel: orgLabel,
			Href:     href,
			Inspect: func(prb ProbeIF) {
				if prb != nil {
					prb.FillUpFormFromGongstruct(auth, "AuthorityForNavaidEquipmentType")
				}
			},
		})
	}
	return out
}

func extractEquipmentStatus(
	avail []*aixmfeatures.NavaidOperationalStatusPropertyType,
	mon []*aixmfeatures.NavaidEquipmentMonitoringPropertyType,
	flightChecked *aixmdatatypes.CodeYesNoType,
) (statusSummary string, monSummary string) {
	var parts []string
	for _, avp := range avail {
		if avp == nil || avp.NavaidOperationalStatus == nil {
			continue
		}
		nos := avp.NavaidOperationalStatus
		if nos.OperationalStatus != nil && strings.TrimSpace(nos.OperationalStatus.EnclosedText) != "" {
			parts = append(parts, strings.TrimSpace(nos.OperationalStatus.EnclosedText))
		}
		if nos.SignalType != nil && strings.TrimSpace(nos.SignalType.EnclosedText) != "" {
			parts = append(parts, "Signal: "+strings.TrimSpace(nos.SignalType.EnclosedText))
		}
	}
	if flightChecked != nil && strings.EqualFold(strings.TrimSpace(flightChecked.EnclosedText), "YES") {
		parts = append(parts, "Flight Checked")
	}
	statusSummary = strings.Join(parts, " | ")

	for _, mp := range mon {
		if mp == nil || mp.NavaidEquipmentMonitoring == nil {
			continue
		}
		nem := mp.NavaidEquipmentMonitoring
		if nem.Monitored != nil && strings.TrimSpace(nem.Monitored.EnclosedText) != "" {
			monSummary = "Monitored: " + strings.TrimSpace(nem.Monitored.EnclosedText)
			break
		}
	}
	return statusSummary, monSummary
}

